using System.Text.Json;
using FaultIQ.Api.Data;
using Microsoft.EntityFrameworkCore;

namespace FaultIQ.Api.Features;

// GET /models (project plan, section 10; ADR 0027). The registry is generated by
// `python -m faultiq export-models` from the committed held-out results and embedded in this
// assembly. Its numbers describe the diagnosis method; model files are trained locally with that
// method, so each entry is joined with the model versions actually recorded on analyses. The API
// never reads the worker's model directory and never loads a model.

public sealed record TrainingSplit(string Train, string Validation);

public sealed record HeldOutResults(
    int TestHours, double TestMacroF1, double ValidationMacroF1, double AnsweredShare,
    double NamedFaultPrecision, double RightFaultOnFaultyHours, double CalibrationError);

public sealed record RegistryModel(
    string Format, string PointSet, string Dataset, string DatasetLabel, string AdoptedModel,
    TrainingSplit TrainedOn, string Evaluation, IReadOnlyList<string> Faults, HeldOutResults HeldOut);

public sealed record ModelRegistryDocument(
    int Version, string DiagnosisVersion, string PipelineVersion, string EvaluatedOn,
    double TargetNamedFaultPrecision, IReadOnlyList<RegistryModel> Models);

/// <summary>A model version recorded on stored analyses, with when and how often it was used.</summary>
public sealed record ModelVersionUse(
    string ModelVersion, IReadOnlyList<string> PipelineVersions, int Analyses,
    DateTimeOffset? FirstUsedAt, DateTimeOffset? LastUsedAt);

public sealed record ModelResponse(
    string Format, string PointSet, string Dataset, string DatasetLabel, string AdoptedModel,
    TrainingSplit TrainedOn, string Evaluation, IReadOnlyList<string> Faults, HeldOutResults HeldOut,
    IReadOnlyList<ModelVersionUse> Versions);

public sealed record ModelsResponse(
    string DiagnosisVersion, string EvaluatedWithPipelineVersion, string EvaluatedOn,
    double TargetNamedFaultPrecision, IReadOnlyList<ModelResponse> Items);

public sealed class ModelRegistryStore
{
    public ModelRegistryDocument Document { get; }

    public ModelRegistryStore()
    {
        using var stream = typeof(ModelRegistryStore).Assembly.GetManifestResourceStream("FaultIQ.ModelRegistry.json")
            ?? throw new InvalidOperationException("The model registry is not embedded in the API assembly.");
        Document = JsonSerializer.Deserialize<ModelRegistryDocument>(stream,
                       new JsonSerializerOptions { PropertyNamingPolicy = JsonNamingPolicy.SnakeCaseLower })
                   ?? throw new InvalidOperationException("The model registry is empty.");
    }
}

public static class ModelEndpoints
{
    public static RouteGroupBuilder MapModelEndpoints(this RouteGroupBuilder api)
    {
        var g = api.MapGroup("/models").WithTags("models");

        g.MapGet("/", async (ModelRegistryStore store, FaultIqDbContext db, CancellationToken ct) =>
        {
            // Grouped by the upload's format and the analysis's point set: the version string is
            // an identifier, never parsed.
            var used = await db.Analyses.AsNoTracking()
                .Where(a => a.ModelVersion != null)
                .Join(db.Uploads, a => a.UploadId, u => u.Id,
                    (a, u) => new { u.Format, a.PointSet, a.ModelVersion, a.PipelineVersion, a.FinishedAt })
                .GroupBy(x => new { x.Format, x.PointSet, x.ModelVersion, x.PipelineVersion })
                .Select(x => new
                {
                    x.Key.Format,
                    x.Key.PointSet,
                    x.Key.ModelVersion,
                    x.Key.PipelineVersion,
                    Count = x.Count(),
                    First = x.Min(r => r.FinishedAt),
                    Last = x.Max(r => r.FinishedAt),
                })
                .ToListAsync(ct);

            var doc = store.Document;
            var items = doc.Models.Select(m => new ModelResponse(
                m.Format, m.PointSet, m.Dataset, m.DatasetLabel, m.AdoptedModel, m.TrainedOn, m.Evaluation,
                m.Faults, m.HeldOut,
                used.Where(u => u.Format == m.Format && u.PointSet == m.PointSet)
                    .GroupBy(u => u.ModelVersion!)
                    .Select(v => new ModelVersionUse(
                        v.Key,
                        v.Select(u => u.PipelineVersion).OfType<string>().Distinct().Order(StringComparer.Ordinal).ToList(),
                        v.Sum(u => u.Count),
                        v.Min(u => u.First),
                        v.Max(u => u.Last)))
                    .OrderByDescending(v => v.LastUsedAt)
                    .ThenBy(v => v.ModelVersion, StringComparer.Ordinal)
                    .ToList())).ToList();
            return TypedResults.Ok(new ModelsResponse(
                doc.DiagnosisVersion, doc.PipelineVersion, doc.EvaluatedOn, doc.TargetNamedFaultPrecision, items));
        }).WithName("ListModels");

        return api;
    }
}
